-- website; camps whose 2026 schedules are behind registration portals / PDFs / not-yet-open
-- registration are intentionally left empty (no fabricated data).
-- Idempotent: deletes existing sessions for ONLY these 8 camps, then re-inserts. Safe to re-run.
-- Run once in the Supabase SQL Editor.
--
-- Notes:
--   * St. Catherine's ages are approximated from published grade levels (rising JK≈4, K≈5,
--     grade N≈N+5); exact daily AM/PM times are not published (left NULL).
--   * Visual Arts Center rows carry confirmed week dates only; per-camp ages/prices are behind
--     the Amilia store's JS accordion and still need enrichment (left NULL).

BEGIN;

-- Clear any existing sessions for just these 8 camps (all currently 0; makes re-runs safe).
DELETE FROM public.camp_sessions WHERE camp_id IN (
  'bc7b3232-2f0c-46b8-b869-5932a3e160a8',  -- Art Factory Summer Art Camp
  '0d9e8c41-1d2a-4d89-b951-06c1d7b5e327',  -- Brilliant Summer at St. Catherine's School
  '3c7ab356-fbb0-4ac6-9e47-3c279f983a86',  -- James River Association Summer Camps
  '4321d3bd-2b8d-44bd-8f0b-94d71affca82',  -- Maymont Summer Discovery Camps
  'e49fa5db-3548-488d-b0c2-b5fc18b4023b',  -- Science Museum of Virginia Summer Camp
  '57bd1cd2-cf11-413b-a05d-ce1c54e7cda6',  -- RITS Summer Camp
  '45d17c65-a8f5-49cc-ae9c-6172c704ee01',  -- Lewis Ginter Botanical Garden Summer Camp
  'c3c9d422-4df3-4677-986b-97e91d07df79'   -- Visual Arts Center of Richmond Summer Camps
);
